 ('cscal', 'scalar multiple', 'tích của một số với một vectơ', 'multiply every coordinate by the same number.', 'nhân mọi tọa độ với cùng một số.', '\\(2(1;2;3)=(2;4;6)\\).', '\\(k\\vec a\\)'),
 ('cdot', 'dot product by coordinates', 'biểu thức tọa độ của tích vô hướng', 'multiply matching coordinates and add: \\(x_1x_2+y_1y_2+z_1z_2\\).', 'nhân các tọa độ tương ứng rồi cộng: \\(x_1x_2+y_1y_2+z_1z_2\\).', '\\((1;2;3)\\cdot(2;0;1)=5\\).', ''),
