 ('cperp', 'perpendicular vectors', 'hai vectơ vuông góc', 'vectors whose dot product is 0.', 'hai vectơ có tích vô hướng bằng 0.', '\\((1;2;2)\\perp(2;-2;1)\\).', '\\(\\vec a\\perp\\vec b\\)'),
